/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: LocalFileEvidence, LookupCandidate, LookupProposal, LookupMatchStatus, LookupDifference,
 *          LookupFileComparison, LookupComparison, RankedLookupCandidate, RankedLookupGroup,
 *          LookupPreselection, RankedLookup
 *   Functions: lookupTrackCountPlausible, legacyDurationEvidence, proposalForRelease, lookupTrackAssignment,
 *              rankLookupCandidates
 * Internal
 *   Functions: clean, folded, canonical, groupKeyFor, byText, orderedFiles, compareRelease, artistMismatchFor,
 *              sharedIdentifier, usableRelease, distinctCandidates
 *   Constants: featuring
 * @end-catalog */

import { createHash } from 'node:crypto';
import { METADATA_LOOKUP_LIMITS, type LookupDate, type MusicBrainzRelease, type MusicBrainzReleaseSummary } from './lookupContract';
import { isPlaceholderCredit, normalizeGtin, normalizeItunesId, normalizeMusicBrainzId } from './lookupIdentifiers';
import { keepableMusicBrainzId } from '../../utils/musicBrainzId';

/**
 * Pure ranking of lookup candidates against the import's selected files. It never makes a request:
 * calling it again with newly known durations re-ranks the stored candidates. Matching candidates
 * all score the same; those that would write identical draft values form one group. The result is
 * identical under any permutation of the inputs. The only matching group is preselected only when
 * the comparison is complete: a search that offered more releases than were compared
 * (`searchComplete: false`) or an incomplete candidate that could match may hide another matching
 * group, so the comparison is disclosed as partial and only an embedded identifier still preselects.
 * An iTunes-only candidate never shares a group with a MusicBrainz one, and is preselected only when
 * MusicBrainz answered without a release for it or stayed unavailable (then flagged `notChecked`).
 */
export type LocalFileEvidence = {
    slotId: string; order: number;
    durationMs: number | null;
    /** 0 for millisecond durations, 1000 for legacy `mm:ss` durations. */
    durationPrecisionMs: 0 | 1000;
    discNumber: number | null; trackNumber: number | null;
    artistTags: string[];
    identifiers: { releaseId: string | null; barcode: string | null; catalogNumber: string | null };
};
export type LookupCandidate = {
    /** For an iTunes-only candidate `releaseId` is its collection ID and `itunesCheck` why it was not checked against MusicBrainz. */
    key: string; source: 'musicbrainz' | 'itunes'; releaseId: string; itunesCheck?: 'noRelease' | 'unavailable' | 'notRun';
    summary: MusicBrainzReleaseSummary | null;
    /** Null when the release details could not be fetched: the candidate is incomplete. */
    release: MusicBrainzRelease | null;
    /** The release total a search reported for a release found without a summary (a recording hit); absent when unknown. */
    reportedTrackCount?: number | null;
    /** The release no longer exists (its lookup answered 404), so, though incomplete, it cannot match. */
    missing?: boolean;
};
/** The draft values a release would write; each Artist entry and the label carry the MusicBrainz ID it credits (null for none). */
export type LookupProposal = {
    albumTitle: string;
    artists: { name: string; role: 'primary' | 'featured'; joinPhrase: string | null; musicBrainzId: string | null }[];
    label: string | null;
    labelMusicBrainzId: string | null;
    releaseDate: LookupDate | null;
    tracks: { discNumber: number; trackNumber: number; title: string }[];
};
export type LookupMatchStatus = 'matching' | 'unverified' | 'notMatching' | 'incomplete';
export type LookupDifference = 'trackCount' | 'discCount' | 'duration';
export type LookupFileComparison = { slotId: string; localMs: number | null; candidateMs: number | null; deltaMs: number | null; withinTolerance: boolean | null };
export type LookupComparison = {
    trackCount: { local: number; candidate: number };
    discCount: { local: number | null; candidate: number };
    files: LookupFileComparison[];
    differences: LookupDifference[];
    unknownLocalDurations: number;
    unknownCandidateDurations: number;
};
export type RankedLookupCandidate = {
    key: string; releaseId: string; status: LookupMatchStatus;
    comparison: LookupComparison | null; proposal: LookupProposal | null;
    groupKey: string | null; artistMismatch: boolean | null;
};
export type RankedLookupGroup = { groupKey: string; representativeKey: string; memberKeys: string[]; proposal: LookupProposal };
/** `notChecked` (present only when true): an iTunes-only candidate preselected while MusicBrainz stayed unavailable. */
export type LookupPreselection = { candidateKey: string; groupKey: string; basis: 'releaseId' | 'barcode' | 'catalogNumber' | 'onlyMatchingGroup'; artistMismatch: boolean; notChecked?: boolean };
export type RankedLookup = {
    candidates: RankedLookupCandidate[];
    groups: RankedLookupGroup[];
    preselection: LookupPreselection | null;
    /** `partialComparison`: not every release the searches offered was compared, so a lone matching group is not proof. */
    disclosure: { unknownLocalDurations: number; unknownLocalDiscNumbers: number; partialComparison: boolean };
};

/** A release whose reported track count is unknown (absent, not a positive integer) can still match; a known one must equal the file count. */
export const lookupTrackCountPlausible = (reported: unknown, fileCount: number): boolean =>
    !(Number.isSafeInteger(reported) && (reported as number) > 0) || reported === fileCount;

/** Legacy durations are stored rounded to whole seconds (`m:ss` or `h:mm:ss`). */
export const legacyDurationEvidence = (value: unknown): { durationMs: number; durationPrecisionMs: 1000 } | null => {
    const match = typeof value === 'string' && value.length <= 16 ? /^(?:(\d+):)?([0-5]?\d):([0-5]\d)$/.exec(value) : null;
    if (!match) return null;
    const durationMs = ((Number(match[1] ?? 0) * 60 + Number(match[2])) * 60 + Number(match[3])) * 1000;
    return durationMs > 0 && Number.isSafeInteger(durationMs) ? { durationMs, durationPrecisionMs: 1000 } : null;
};

const featuring = /(?:^|[\s(（])(?:feat\.?|ft\.?|featuring)(?=$|[\s.)）])/i;
const clean = (value: string) => value.normalize('NFC').trim();
const folded = (value: string) => clean(value).toLowerCase();

/**
 * The draft values a release would write; placeholders and a `[no label]` label are never proposed, and a credit that repeats an
 * earlier one's MusicBrainz artist or folded name is dropped (only its first entry is kept). A dropped credit's join phrase is
 * not moved, as with placeholders: a byline ignores a trailing phrase. Each entry and the label carry the MusicBrainz ID the
 * release credits, so candidates that credit different artists or labels under one name are different proposals.
 */
export const proposalForRelease = (release: MusicBrainzRelease): LookupProposal => {
    let featured = false;
    const artists: LookupProposal['artists'] = [], seen = new Set<string>();
    for (const credit of release.artistCredit) {
        const role = featured ? 'featured' as const : 'primary' as const;
        // The entry after a featuring phrase, and every later entry, is featured.
        if (featuring.test(credit.joinPhrase)) featured = true;
        if (isPlaceholderCredit(credit.name, credit.artistId) || isPlaceholderCredit(credit.artistName)) continue;
        const artistId = normalizeMusicBrainzId(credit.artistId), name = `name:${folded(credit.name)}`;
        if ((artistId && seen.has(`id:${artistId}`)) || seen.has(name)) continue;
        if (artistId) seen.add(`id:${artistId}`);
        seen.add(name);
        // Join phrases keep their surrounding spaces: they are part of the byline presentation.
        const joinPhrase = credit.joinPhrase.normalize('NFC');
        artists.push({ name: clean(credit.name), role, joinPhrase: joinPhrase ? joinPhrase : null, musicBrainzId: keepableMusicBrainzId(artistId) });
    }
    const first = release.labels.find(label => label.name !== null || label.labelId !== null);
    const label = first?.name && !isPlaceholderCredit(first.name, first.labelId) ? clean(first.name) : null;
    return {
        albumTitle: clean(release.title), artists, label, labelMusicBrainzId: label === null ? null : keepableMusicBrainzId(first!.labelId),
        releaseDate: release.groupFirstReleaseDate ?? release.date,
        // Discs are numbered among the media that have tracks, as the disc-count comparison counts them,
        // so a CD after a DVD without a tracklist is Disc Number 1.
        tracks: release.media.filter(medium => medium.tracks.length).flatMap((medium, index) =>
            medium.tracks.map(track => ({ discNumber: index + 1, trackNumber: track.position, title: clean(track.title) })))
    };
};

const canonical = (value: unknown): string => {
    if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
    if (value && typeof value === 'object') return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${canonical((value as Record<string, unknown>)[key])}`).join(',')}}`;
    return JSON.stringify(value);
};
/** MusicBrainz group keys hash the proposal alone, as before iTunes candidates existed; iTunes ones also name the source, so groups never mix sources. */
const groupKeyFor = (proposal: LookupProposal, source: LookupCandidate['source']) =>
    createHash('sha256').update(canonical(source === 'itunes' ? { source: 'itunes', proposal } : proposal)).digest('hex');
const byText = (left: string, right: string) => left < right ? -1 : left > right ? 1 : 0;

/**
 * Deterministic file order: Disc Number (unknown counts as 1), Track Number (unknown last), then
 * upload order. When some Disc Numbers are unknown and Track Numbers repeat (numbering restarts
 * on every disc), disc membership cannot be inferred, so upload order alone decides.
 */
const orderedFiles = (files: readonly LocalFileEvidence[]) => {
    const tracks = files.map(file => file.trackNumber).filter((track): track is number => track !== null);
    const byUpload = files.some(file => file.discNumber === null) && new Set(tracks).size !== tracks.length;
    return [...files].sort((left, right) => (byUpload ? 0
        : (left.discNumber ?? 1) - (right.discNumber ?? 1)
        || (left.trackNumber ?? Number.POSITIVE_INFINITY) - (right.trackNumber ?? Number.POSITIVE_INFINITY))
        || left.order - right.order || byText(left.slotId, right.slotId));
};

/**
 * The candidate track each local file takes when the track counts agree: the ranking's file order paired with the proposal's
 * tracks in medium order (the flattening the comparison uses), with each track's Disc Number among the media that have tracks.
 * Null when the counts differ. Pure.
 */
export const lookupTrackAssignment = (release: MusicBrainzRelease, files: readonly LocalFileEvidence[]):
    { slotId: string; discNumber: number; trackNumber: number; title: string }[] | null => {
    const tracks = proposalForRelease(release).tracks, ordered = orderedFiles(files);
    if (!ordered.length || tracks.length !== ordered.length) return null;
    return ordered.map((file, index) => ({ slotId: file.slotId, ...tracks[index] }));
};

const compareRelease = (release: MusicBrainzRelease, files: readonly LocalFileEvidence[], toleranceMs: number) => {
    const tracks = release.media.flatMap(medium => medium.tracks);
    const counted = files.length === tracks.length;
    const localDiscs = files.length && files.every(file => file.discNumber !== null) ? new Set(files.map(file => file.discNumber)).size : null;
    const candidateDiscs = release.media.filter(medium => medium.tracks.length).length;
    const rows: LookupFileComparison[] = files.map((file, index) => {
        const candidateMs = counted ? tracks[index].lengthMs : null;
        const known = counted && file.durationMs !== null && candidateMs !== null;
        const deltaMs = known ? file.durationMs! - candidateMs! : null;
        return { slotId: file.slotId, localMs: file.durationMs, candidateMs, deltaMs,
            withinTolerance: deltaMs === null ? null : Math.abs(deltaMs) <= toleranceMs + file.durationPrecisionMs };
    });
    const differences: LookupDifference[] = [];
    if (!counted) differences.push('trackCount');
    if (localDiscs !== null && localDiscs !== candidateDiscs) differences.push('discCount');
    if (rows.some(row => row.withinTolerance === false)) differences.push('duration');
    const comparison: LookupComparison = {
        trackCount: { local: files.length, candidate: tracks.length },
        discCount: { local: localDiscs, candidate: candidateDiscs },
        files: rows, differences,
        unknownLocalDurations: files.filter(file => file.durationMs === null).length,
        unknownCandidateDurations: tracks.filter(track => track.lengthMs === null).length
    };
    const status: LookupMatchStatus = differences.length ? 'notMatching'
        : comparison.unknownLocalDurations || comparison.unknownCandidateDurations ? 'unverified' : 'matching';
    const order = [
        Math.abs(files.length - tracks.length),
        localDiscs === null ? 0 : Math.abs(localDiscs - candidateDiscs),
        counted ? rows.reduce((sum, row) => sum + Math.abs(row.deltaMs ?? 0), 0) : 0
    ];
    return { comparison, status, order };
};

/**
 * True when artist tags exist and none equals the joined credit, a credited name, a canonical artist name, an alias the lookup
 * found for a credited artist (`aliases`, by MusicBrainz ID) or another name of an iTunes localized name group (`localized`) that
 * holds one of those names.
 */
const artistMismatchFor = (release: MusicBrainzRelease, files: readonly LocalFileEvidence[], aliases?: ReadonlyMap<string, readonly string[]>,
    localized?: readonly (readonly string[])[]) => {
    const tags = new Set(files.flatMap(file => file.artistTags).filter(tag => typeof tag === 'string').map(folded).filter(Boolean));
    if (!tags.size) return false;
    const names = new Set([
        folded(release.artistCredit.map(credit => credit.name + credit.joinPhrase).join('')),
        ...release.artistCredit.flatMap(credit => [folded(credit.name), folded(credit.artistName),
            ...(aliases?.get(normalizeMusicBrainzId(credit.artistId) ?? '') ?? []).filter(name => typeof name === 'string').map(folded)])
    ]);
    const groups = (Array.isArray(localized) ? localized : []).map(group => (Array.isArray(group) ? group : []).filter((name): name is string => typeof name === 'string').map(folded));
    for (const group of groups.filter(group => group.some(name => names.has(name)))) for (const name of group) names.add(name);
    return ![...tags].some(tag => names.has(tag));
};

/** An identifier counts only when every file carries the same valid value. */
const sharedIdentifier = (files: readonly LocalFileEvidence[], read: (file: LocalFileEvidence) => string | null) => {
    const values = new Set(files.map(read));
    const [value] = values;
    return files.length && values.size === 1 && value ? value : null;
};

/**
 * A fetched release counts only when it is the candidate's own release (by MusicBrainz ID, or for an iTunes-only candidate by its
 * collection ID); otherwise the candidate is incomplete.
 */
const usableRelease = (candidate: LookupCandidate) => !candidate.release ? null
    : candidate.source === 'itunes' ? normalizeItunesId(candidate.releaseId) !== null && candidate.release.releaseId === candidate.releaseId ? candidate.release : null
        : normalizeMusicBrainzId(candidate.releaseId) !== null && normalizeMusicBrainzId(candidate.release.releaseId) === normalizeMusicBrainzId(candidate.releaseId) ? candidate.release : null;

/** Duplicate keys keep the most complete entry, chosen without regard to input order. */
const distinctCandidates = (candidates: readonly LookupCandidate[]) => {
    const chosen = new Map<string, LookupCandidate>();
    const weight = (candidate: LookupCandidate) => (usableRelease(candidate) ? 2 : 0) + (candidate.summary ? 1 : 0);
    for (const candidate of candidates) {
        const current = chosen.get(candidate.key);
        if (!current || weight(candidate) > weight(current)
            || (weight(candidate) === weight(current) && canonical(candidate) < canonical(current))) chosen.set(candidate.key, candidate);
    }
    return [...chosen.values()];
};

/**
 * `searchComplete` false marks a comparison partial; left out, the searches count as complete (pure callers and tests). An
 * incomplete candidate makes it partial too, unless it cannot match: it no longer exists or reported another track count.
 * `aliases` are the artist aliases the run found, by MusicBrainz ID, and `localized` its iTunes localized name groups
 * (artistMismatchFor). An iTunes-only candidate is preselectable only when its check is `noRelease` or `unavailable`: an
 * identifier that names one that is not preselects nothing, and neither does an only matching group it represents.
 */
export const rankLookupCandidates = (candidates: readonly LookupCandidate[], files: readonly LocalFileEvidence[],
    options: { toleranceMs?: number; searchComplete?: boolean; aliases?: ReadonlyMap<string, readonly string[]>; localized?: readonly (readonly string[])[] } = {}): RankedLookup => {
    const toleranceMs = options.toleranceMs ?? METADATA_LOOKUP_LIMITS.durationToleranceMs;
    const sorted = orderedFiles(files), distinct = distinctCandidates(candidates);
    type Scored = RankedLookupCandidate & { order: number[]; frontArtwork: boolean; release: MusicBrainzRelease | null; source: LookupCandidate['source'];
        preselectable: boolean; notChecked: boolean };
    const scored: Scored[] = distinct.map(candidate => {
        const release = usableRelease(candidate), source = candidate.source === 'itunes' ? 'itunes' as const : 'musicbrainz' as const;
        const preselectable = source !== 'itunes' || candidate.itunesCheck === 'noRelease' || candidate.itunesCheck === 'unavailable';
        const notChecked = source === 'itunes' && candidate.itunesCheck === 'unavailable';
        if (!release) return { key: candidate.key, releaseId: candidate.releaseId, status: 'incomplete', comparison: null, proposal: null,
            groupKey: null, artistMismatch: null, order: [], frontArtwork: false, release: null, source, preselectable, notChecked };
        const { comparison, status, order } = compareRelease(release, sorted, toleranceMs);
        const proposal = proposalForRelease(release);
        return { key: candidate.key, releaseId: candidate.releaseId, status, comparison, proposal,
            groupKey: status === 'matching' ? groupKeyFor(proposal, source) : null, artistMismatch: artistMismatchFor(release, files, options.aliases, options.localized),
            order, frontArtwork: release.frontArtwork === true, release, source, preselectable, notChecked };
    });

    const byRepresentative = (left: Scored, right: Scored) => Number(right.frontArtwork) - Number(left.frontArtwork) || byText(left.releaseId, right.releaseId) || byText(left.key, right.key);
    const members = new Map<string, Scored[]>();
    for (const candidate of scored) if (candidate.groupKey) members.set(candidate.groupKey, [...(members.get(candidate.groupKey) ?? []), candidate]);
    const groups = [...members.entries()].map(([groupKey, list]) => {
        const ordered = [...list].sort(byRepresentative);
        return { groupKey, representative: ordered[0], members: ordered };
    }).sort((left, right) => byText(left.representative.key, right.representative.key));

    const others = scored.filter(candidate => candidate.status === 'notMatching' || candidate.status === 'unverified').sort((left, right) =>
        left.order[0] - right.order[0] || left.order[1] - right.order[1] || left.order[2] - right.order[2]
        || byText(left.releaseId, right.releaseId) || byText(left.key, right.key));
    const incomplete = scored.filter(candidate => candidate.status === 'incomplete').sort((left, right) => byText(left.key, right.key));
    const strip = ({ order: _order, frontArtwork: _frontArtwork, release: _release, source: _source, preselectable: _preselectable, notChecked: _notChecked, ...candidate }: Scored): RankedLookupCandidate => candidate;
    const ranked = [...groups.flatMap(group => group.members), ...others, ...incomplete].map(strip);

    const matching = scored.filter(candidate => candidate.status === 'matching');
    const select = (candidate: Scored, basis: LookupPreselection['basis']): LookupPreselection => ({ candidateKey: candidate.key, groupKey: candidate.groupKey!, basis,
        artistMismatch: candidate.artistMismatch === true, ...(candidate.notChecked ? { notChecked: true } : {}) });
    let preselection: LookupPreselection | null = null;
    const identifierRules: [LookupPreselection['basis'], string | null, (candidate: Scored, value: string) => boolean][] = [
        ['releaseId', sharedIdentifier(files, file => normalizeMusicBrainzId(file.identifiers.releaseId)),
            (candidate, value) => normalizeMusicBrainzId(candidate.releaseId) === value],
        ['barcode', sharedIdentifier(files, file => normalizeGtin(file.identifiers.barcode)?.gtin14 ?? null),
            (candidate, value) => normalizeGtin(candidate.release?.barcode ?? null)?.gtin14 === value],
        ['catalogNumber', sharedIdentifier(files, file => typeof file.identifiers.catalogNumber === 'string' && folded(file.identifiers.catalogNumber) ? folded(file.identifiers.catalogNumber) : null),
            (candidate, value) => (candidate.release?.labels ?? []).some(label => label.catalogNumber !== null && folded(label.catalogNumber) === value)]
    ];
    for (const [basis, value, matches] of identifierRules) {
        if (!value) continue;
        const hits = matching.filter(candidate => matches(candidate, value));
        // A lone hit that may not be preselected (an iTunes-only candidate not yet ruled out in MusicBrainz) preselects nothing.
        if (hits.length === 1) { if (hits[0].preselectable) preselection = select(hits[0], basis); break; }
    }
    const partialComparison = options.searchComplete === false || distinct.some(candidate => !usableRelease(candidate) && candidate.missing !== true
        && lookupTrackCountPlausible(candidate.summary?.trackCount ?? candidate.reportedTrackCount, files.length));
    if (!preselection && groups.length === 1 && !partialComparison && groups[0].representative.preselectable) preselection = select(groups[0].representative, 'onlyMatchingGroup');

    return {
        candidates: ranked,
        groups: groups.map(group => ({ groupKey: group.groupKey, representativeKey: group.representative.key,
            memberKeys: group.members.map(member => member.key), proposal: group.representative.proposal! })),
        preselection,
        disclosure: {
            unknownLocalDurations: files.filter(file => file.durationMs === null).length,
            unknownLocalDiscNumbers: files.filter(file => file.discNumber === null).length,
            partialComparison
        }
    };
};
